import sys; sys.path.insert(0,'/workspace/work')
exec(open('/workspace/work/exp25.py').read().split("# ============ EXPERIMENT")[0])
import numpy as np
K=0.089489; C=440/K
def rel_for(fs): return 12*(np.log2(C) - 21/12 - np.log2(fs))
def saw(fs, nharm=12, amp=20000, sr=44100, extra_cycles=40):
    N = sr/fs
    n = int(N)+int(extra_cycles*N)+10
    t=np.arange(n)/N
    sig=np.zeros(n)
    for h in range(1,nharm+1): sig += np.sin(2*np.pi*h*t)/h
    return sig/np.abs(sig).max()*amp, int(round(N))
def pitch(m): return 440*2**((m-69)/12)

fs=307.3
sig,N=saw(fs)
print('N =',N,'len',len(sig))
for rel in [0, 12, 24, 27, 28, 36, 15, 3, -9]:
