# Determine FT2 note numbering empirically instead: earlier note 58 = "A-4" per pattern_get_cell.
# So A-4 = 58 in this FT2 build. Then C-4 = 58-9 = 49. Let's verify.
import sys; sys.path.insert(0,'/workspace/work')
from ft2lib import call
call('module_new',{'channels':4,'name':'t'})
import json,subprocess
for nm in ['C-4','A-4','C-3','A-3','C-5','A-5','C-2','E-4','B-4','C#4','Bb4']:
    r=subprocess.run(['ft2','call','pattern_set_cell',json.dumps({'pattern':0,'row':0,'channel':0,'note':nm})],capture_output=True,text=True)
    try:
        j=json.loads(r.stdout); t=j['content'][0]['text']
        try:
            d=json.loads(t); print(nm,'->',d.get('note'),d.get('note_name'))
        except Exception: print(nm,'->',t[:80])
    except Exception: print(nm,'ERR',r.stdout[:100],r.stderr[:200])
EOF"}

