def pitch_of(note):
    """note: FT2 note number (C-4=49, A-4=58). Returns Hz."""
    return 440.0 * 2.0**((note-58)/12.0)

NOTE_NAMES = ['C','C#','D','D#','E','F','F#','G','G#','A','A#','B']
def nn(name):
    """Note name -> FT2 note number. Verified: C-4 = 49, A-4 = 58, C-0 = 1."""
    name = name.strip().upper()
    i = 1
    if len(name)>1 and name[1] in '#B':
        i = 2
    semi = {'C':0,'D':2,'E':4,'F':5,'G':7,'A':9,'B':11}[name[0]]
    if i==2:
        if name[1]=='#': semi += 1
        else: semi -= 1
    octv = int(name[i:])
    return (octv+1)*12 + semi - 11   # C-4 -> 49, A-4 -> 58

def rel_for_fs(fs):
    """relative_note so a sample with fundamental fs Hz, played at its true note
    name, sounds in tune:  r = 12*log2(440*2^(-9/12)/(K*fs))"""
    return 12.0*(np.log2(440.0*2.0**(-9.0/12.0)) - np.log2(K) - np.log2(fs))

