import numpy as np

def build_instr(kind, fs, nharm=10, amp=20000, attack_s=0.004, extra_cycles=60, rel=None):
    fs_a, rel_f = octave_align_fs(fs)
    if rel is not None: rel_f = rel; fs_a = fs_for_rel(rel)
    N = int(round(SR/fs_a))
    fs_eff = SR/N
    n_loop = extra_cycles*N
    n_att = int(attack_s*SR)
    n = n_att + n_loop
    tl = np.arange(n_loop)/N
    ta = np.arange(max(n_att,1))/N
    def wave(t):
        if kind=='saw':   return sum(np.sin(2*np.pi*(h+1)*t)/(h+1) for h in range(nharm))
        if kind=='square':return sum(np.sin(2*np.pi*(2*h+1)*t)/(2*h+1) for h in range(nharm))
        if kind=='tri':   return sum(((-1)**h)*np.sin(2*np.pi*(2*h+1)*t)/(2*h+1)**2 for h in range(nharm))
        if kind=='sine':  return np.sin(2*np.pi*t)
        if kind=='organ': return sum(np.sin(2*np.pi*(h+1)*t) for h in range(nharm))
        if kind=='pulse': return sum(np.sin(2*np.pi*(h+1)*t)/(h+1)*((-1)**(h//2)) for h in range(nharm))
        raise ValueError(kind)
    loop = wave(tl); loop = loop/np.abs(loop).max()*amp
    att = wave(ta); 
    if np.abs(att).max()>0: att = att/np.abs(att).max()*amp
    env = np.linspace(0,1,max(n_att,1))**0.5
    att = att*env
